import { Link } from "react-router-dom";
import { useEffect,useState } from "react";
import axios  from "axios";
const baseUrl="http://127.0.0.1:8000/api/teacher/"
function Teacherregister() {
    const[teacherData,setTeacherData]=useState({
        "full_name":"",
        "email":"",
        "password":"",
        "qualification":"",
        "mobile_no":"",
        "skills":"",
        "status":""
    });
    //change Element value
    const handleChange=(event)=>{
        setTeacherData({
            ...teacherData,
            [event.target.name]:event.target.value
        });
    }
    //submitform
    const submitForm=()=>{
        const tearcherFormData=new FormData();
        tearcherFormData.append("full_name",teacherData.full_name)
        tearcherFormData.append("email",teacherData.email)
        tearcherFormData.append("password",teacherData.password)
        tearcherFormData.append("qualification",teacherData.qualification)
        tearcherFormData.append("mobile_no",teacherData.mobile_no)
        tearcherFormData.append("skills",teacherData.skills)

        try{

        
        axios.post(baseUrl,tearcherFormData.then((response)=>{
            setTeacherData({
        "full_name":"",
        "email":"",
        "password":"",
        "qualification":"",
        "mobile_no":"",
        "skills":"",
        "status":"success"
            })
        }))
    }
    catch(error){
        console.log(error);
        setTeacherData({'status':"error"})
    };
    };
    useEffect(()=>{
        document.title="Teacher Registration"
      })
  return (
      <div className="container mt-4">
        <div className="row">
            <div className="col-6 offset-3">
                {teacherData.status=="success" && <p className="text-success">Thanks for the registration</p>}
                {!teacherData.status=="error" && <p className="text-danger">something went wrong</p>}
                <div className="card">
                    <h5 className="card-header">Teacher Register</h5>
                    <div className="card-body">
                        <form>
                            <div className="mb-3">
                                <label htmlFor="name" className="form-label">Full Name</label>
                                <input value={teacherData.full_name} onChange={handleChange} type="text" name="full_name" className="form-control" id="name"/>
                            </div>
                            <div className="mb-3">
                                <label htmlFor="email" className="form-label">Email</label>
                                <input value={teacherData.email} onChange={handleChange} type="email" name="email" className="form-control" id="email"/>
                            </div>
                            <div className="mb-3">
                                <label htmlFor="password" className="form-label">Password</label>
                                <input value={teacherData.password} onChange={handleChange} type="password" name="password" className="form-control" id="password"/>
                            </div>
                            <div className="mb-3">
                                <label htmlFor="qualification" className="form-label">Qualification</label>
                                <input value={teacherData.qualification} onChange={handleChange} type="text" name="qualification" className="form-control" id="qualification"/>
                            </div>
                            <div className="mb-3">
                                <label htmlFor="Mobile Number" className="form-label">Mobile Number</label>
                                <input onChange={handleChange} type="text" name="mobile_no" className="form-control"/>
                            </div>
                            <div className="mb-3">
                                <label htmlFor="skills" className="form-label">skills</label>
                                <textarea name="skills" onChange={handleChange} className="form-control"></textarea>
                                <div id="help" className="form-text">Webdev, dataScience, Python</div>
                            </div>
                            <button type="submit" onClick={submitForm} className="btn btn-primary">Register</button>
                        </form>
                    </div>
                </div>
            </div>
        </div>
      </div>
  )
}

export default Teacherregister;
